{
  "status": "modified",
  "reason": "The title has been changed from 'Hosted options' to 'Hosting Platforms'.",
  "old_quote": "\"# Hosted options\"",
  "new_quote": "\"# Hosting Platforms\""
}

{
  "status": "modified",
  "reason": "The location of the deployment instruction has changed from 'on PythonAnywhere' to just 'PythonAnywhere'.",
  "old_quote": "- Deploying on PythonAnywhere",
  "new_quote": "- PythonAnywhere"
}

{
  "status": "modified",
  "reason": "The after passage omits the information about deploying Flask.",
  "old_quote": "- Deploying Flask on Google App Engine",
  "new_quote": "- Google App Engine"
}

{
  "status": "modified",
  "reason": "The location of the action has changed from being part of a step to just mentioning the service.",
  "old_quote": "- Deploying Flask on AWS Elastic Beanstalk",
  "new_quote": "- AWS Elastic Beanstalk"
}

{
  "status": "modified",
  "reason": "The after passage introduces new information about default solutions being tradeoffs, depending on specific needs, and mentions that some security issues might be handled by hosting platforms.",
  "old_quote": "\"Flask tries to solve a few of these things for you, but there are a couple more you have to take care of yourself.\"",
  "new_quote": "\"Flask tries to solve a few of these things by default, but there are other parts you may have to take care of yourself. Many of these solutions are tradeoffs, and will depend on each application's specific needs and threat model. Many hosting platforms may take care of certain types of problems without the need for the Flask application to handle them.\""
}

{
  "status": "modified",
  "reason": "The path separator has changed from a dot (.) to a slash (/).",
  "old_quote": ".pythoncollection.",
  "new_quote": "/example/pythoncollection"
}

{
  "status": "modified",
  "reason": "The after passage omits the '/ import rules' part which is present in the before passage.",
  "old_quote": "/ import rules",
  "new_quote": ""
}

{
  "status": "modified",
  "reason": "The original statement was an intention without any conditions or outcomes, while the new one includes a change in plans and reasons.",
  "old_quote": "We intend to make importlib the default in future releases.",
  "new_quote": "it is clear now that it has its own set of drawbacks so the default will remain prepend for the foreseeable future."
}

{
    "status": "modified",
    "reason": "The minimum supported version of Python has been updated from 3.5 to 3.8.",
    "old_quote": "Python 2.7 & 3.5+",
    "new_quote": "Python 3.8+"
}
